window.LQTACAudioLive=(()=>{
class Graph {
 constructor(media){this.media=media;this.context=new AudioContext({latencyHint:'interactive'});this.source=this.context.createMediaElementSource(media);this.analyser=this.context.createAnalyser();this.analyser.fftSize=1024;this.output=this.context.createGain();this.output.gain.value=1;this.worklet=null;this.closed=false;this.current={};this.guide=null;this.ready=this.setup();}
 async setup(){const c=this.context;this.eq=[120,1000,8000].map(hz=>{const n=c.createBiquadFilter();n.type='peaking';n.frequency.value=hz;n.Q.value=1;return n;});this.comp=c.createDynamicsCompressor();this.comp.attack.value=.01;this.comp.release.value=.15;this.comp.knee.value=0;this.comp.ratio.value=1;
 this.hp=c.createBiquadFilter();this.hp.type='highpass';this.hp.frequency.value=10;this.lp=c.createBiquadFilter();this.lp.type='lowpass';this.lp.frequency.value=22000;this.deess=c.createBiquadFilter();this.deess.type='peaking';this.deess.frequency.value=7000;this.deess.Q.value=1.5;
 let node=this.source;for(const n of [this.hp,this.lp,...this.eq,this.deess,this.comp]){node.connect(n);node=n;}
 // Chorus: modulated short delay mixed with the dry signal. Tremolo: gain modulated by an LFO.
 const chorusSum=c.createGain();node.connect(chorusSum);this.chorusDelay=c.createDelay(.1);this.chorusDelay.delayTime.value=.018;this.chorusWet=c.createGain();this.chorusWet.gain.value=0;this.chorusLfo=c.createOscillator();this.chorusLfo.frequency.value=.35;this.chorusDepth=c.createGain();this.chorusDepth.gain.value=0;this.chorusLfo.connect(this.chorusDepth);this.chorusDepth.connect(this.chorusDelay.delayTime);node.connect(this.chorusDelay);this.chorusDelay.connect(this.chorusWet);this.chorusWet.connect(chorusSum);
 this.trem=c.createGain();this.trem.gain.value=1;this.tremLfo=c.createOscillator();this.tremLfo.frequency.value=5;this.tremDepth=c.createGain();this.tremDepth.gain.value=0;this.tremLfo.connect(this.tremDepth);this.tremDepth.connect(this.trem.gain);chorusSum.connect(this.trem);this.chorusLfo.start();this.tremLfo.start();node=this.trem;
 this.echo=c.createDelay(1.1);this.echoGain=c.createGain();this.echoGain.gain.value=0;node.connect(this.echo);this.echo.connect(this.echoGain);const echoSum=c.createGain();node.connect(echoSum);this.echoGain.connect(echoSum);
 this.reverbGain=c.createGain();this.reverbGain.gain.value=0;const taps=[29,43,71,113,173,251],weights=[.55,.45,.35,.25,.18,.1];this.taps=taps.map((ms,i)=>{const d=c.createDelay(.3),g=c.createGain();d.delayTime.value=ms/1000;g.gain.value=weights[i];echoSum.connect(d);d.connect(g);g.connect(this.reverbGain);return [d,g];});const sum=c.createGain();echoSum.connect(sum);this.reverbGain.connect(sum);
 // Convolution reverb with the same kind of synthetic room response as the render (approximate level).
 const convSum=c.createGain();sum.connect(convSum);this.convolver=c.createConvolver();this.convWet=c.createGain();this.convWet.gain.value=0;sum.connect(this.convolver);this.convolver.connect(this.convWet);this.convWet.connect(convSum);this.convSize=0;const afterConv=convSum;
 this.panner=c.createStereoPanner();this.panner.connect(this.analyser);try{await c.audioWorklet.addModule(new URL('assets/autotune-core.js',location.href).href);await c.audioWorklet.addModule(new URL('assets/audio-preview-worklet.js',location.href).href);if(this.closed)return;this.worklet=new AudioWorkletNode(c,'lqtac-audition',{outputChannelCount:[2]});afterConv.connect(this.worklet);this.worklet.connect(this.panner);}catch(e){if(this.closed)return;afterConv.connect(this.panner);this.warning='Ruido/normalización/limitador no disponibles en preescucha: '+e.message;}
 this.analyser.connect(this.output);this.output.connect(c.destination);this.update(this.current.fx||{},this.current.bypass);}
 // Guide melody (MIDI per hop, clip-local seconds) for the live autotune; the editor passes the clip time with each update.
 setGuide(guide){this.guide=guide?.melody?guide:null;this.update(this.current.fx||{},this.current.bypass,this.current.time);}
 update(fx,bypass=false,time=this.clock?this.clock():0){this.current={fx,bypass,time};if(!this.eq)return;const c=this.context,t=c.currentTime,f=bypass?{}:fx;for(let i=0;i<3;i++)this.eq[i].gain.setTargetAtTime(f[['bass','mid','treble'][i]]||0,t,.015);this.comp.threshold.setTargetAtTime(f.compressor?f.thresholdDb:-24,t,.015);this.comp.ratio.setTargetAtTime(f.compressor?f.ratio:1,t,.015);this.echo.delayTime.setTargetAtTime((f.echoMs||250)/1000,t,.025);this.echoGain.gain.setTargetAtTime(f.echo?f.echoMix:0,t,.015);this.reverbGain.gain.setTargetAtTime(f.reverb?f.reverbMix:0,t,.015);
 this.hp.frequency.setTargetAtTime(f.highpass?f.highpassHz:10,t,.02);this.lp.frequency.setTargetAtTime(f.lowpass?f.lowpassHz:22000,t,.02);this.deess.gain.setTargetAtTime(f.deesser?-9*(f.deesserAmount??.5):0,t,.02);
 this.chorusWet.gain.setTargetAtTime(f.chorus?.6*(f.chorusMix??.5):0,t,.02);this.chorusDepth.gain.setTargetAtTime(f.chorus?.004*(f.chorusDepth??.5):0,t,.02);
 const depth=f.tremolo?(f.tremoloDepth??.5):0;this.tremLfo.frequency.setTargetAtTime(f.tremoloHz||5,t,.02);this.tremDepth.gain.setTargetAtTime(depth/2,t,.02);this.trem.gain.setTargetAtTime(1-depth/2,t,.02);
 if(f.convReverb){const size=f.convSize||1.5;if(Math.abs(size-this.convSize)>.01){const data=LQTACEffects.convolutionImpulse(c.sampleRate,size),buffer=c.createBuffer(2,data[0].length,c.sampleRate);buffer.copyToChannel(data[0],0);buffer.copyToChannel(data[1],1);this.convolver.buffer=buffer;this.convSize=size;}}this.convWet.gain.setTargetAtTime(f.convReverb?(f.convMix??.3):0,t,.02);this.panner?.pan.setTargetAtTime(f.pan?(f.panPosition||0):0,t,.02);if(this.worklet){const values={autotune:f.autotune?1:0,autotuneKey:f.autotuneKey||0,autotuneScale:Math.max(0,LQTACEffects.autotuneScales.indexOf(f.autotuneScale||'chromatic')),autotuneSpeed:f.autotuneSpeed??.1,autotuneAmount:f.autotuneAmount??1,autotuneRange:f.autotuneRange??2.5,guideActive:f.autotune&&f.autotuneGuideTrack?1:0,guideMidi:this.guideAt(f,time),guideMode:f.autotuneGuideMode==='contour'?1:0,guideFallback:f.autotuneGuideFallback==='none'?1:0,pitch:f.pitch?1:0,pitchSemitones:f.pitchSemitones||0,gate:f.gate?1:0,gateDb:f.gateDb??-45,lofi:f.lofi?1:0,lofiAmount:f.lofiAmount??.5,widen:f.widen?1:0,widenAmount:f.widenAmount??1.5,denoise:f.denoise?1:0,noiseDb:f.denoiseDb||0,normalize:f.normalize?1:0,targetLufs:f.targetLufs??-16,limiter:f.limiter?1:0,ceiling:f.limiterCeiling??.95};for(const [k,v]of Object.entries(values))this.worklet.parameters.get(k).setValueAtTime(v,t);}}
 guideAt(f,time){const g=this.guide;if(!g||!f.autotuneGuideTrack)return 0;const i=Math.round((time-(f.autotuneGuideOffset||0))/g.hop);return i>=0&&i<g.melody.length?g.melody[i]:0;}
 async resume(){await this.ready;await this.context.resume();}
 peaks(){const a=new Float32Array(1024);this.analyser.getFloatTimeDomainData(a);return Array.from({length:180},(_,i)=>Math.max(...a.slice(Math.floor(i*a.length/180),Math.floor((i+1)*a.length/180)).map(Math.abs)));}
 close(){this.closed=true;try{this.chorusLfo.stop();this.tremLfo.stop();}catch{}this.source.disconnect();this.output.disconnect();void this.context.close();}
}
return {Graph};})();
